        Markup("a"),
        Markup("b"),
        Markup("c"),
    ]


def test_split_maxsplit_large() -> None:
    assert Markup("a b c").split(maxsplit=100) == [
        Markup("a"),
        Markup("b"),
        Markup("c"),
    ]


