import pytest

from click._textwrap import TextWrapper


def make_wrapper(initial="I:", subsequent="S:"):
    return TextWrapper(initial_indent=initial, subsequent_indent=subsequent)


def test_single_line_uses_initial_indent():
    wrapper = make_wrapper()
    assert wrapper.indent_only("hello") == "I:hello"


def test_second_line_uses_subsequent_indent():
    wrapper = make_wrapper()
    result = wrapper.indent_only("first\nsecond")
    assert result == "I:first\nS:second"


def test_third_line_uses_subsequent_indent():
    wrapper = make_wrapper()
    result = wrapper.indent_only("a\nb\nc")
    assert result == "I:a\nS:b\nS:c"


def test_many_lines_all_after_first_use_subsequent_indent():
    wrapper = make_wrapper(initial="  ", subsequent="    ")
    result = wrapper.indent_only("one\ntwo\nthree\nfour")
    assert result == "  one\n    two\n    three\n    four"


def test_empty_string_returns_empty():
    wrapper = make_wrapper()
    assert wrapper.indent_only("") == ""


def test_empty_indents_leave_text_unchanged():
    wrapper = make_wrapper(initial="", subsequent="")
    assert wrapper.indent_only("x\ny\nz") == "x\ny\nz"


def test_trailing_newline_produces_no_extra_line():
    wrapper = make_wrapper()
    # splitlines drops the trailing empty segment, so only two lines remain.
    assert wrapper.indent_only("first\nsecond\n") == "I:first\nS:second"


def test_blank_second_line_still_gets_subsequent_indent():
    wrapper = make_wrapper()
    assert wrapper.indent_only("first\n\nthird") == "I:first\nS:\nS:third"

