import pytest
from datetime import datetime, timedelta, tzinfo

from dateutil.tz._common import _validate_fromutc_inputs


class _RecordingTZ(tzinfo):
    def __init__(self):
        self.utcoff = timedelta(hours=2)
        self.fromutc_calls = 0

    def utcoffset(self, dt):
        return self.utcoff

    def dst(self, dt):
        return timedelta(0)

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.fromutc_calls += 1
        return dt + self.utcoff


class _OtherTZ(tzinfo):
    def utcoffset(self, dt):
        return timedelta(hours=1)

    def dst(self, dt):
        return timedelta(0)


def test_fromutc_rejects_naive_datetime():
    tz = _RecordingTZ()
    dt = datetime(2020, 1, 1)

    with pytest.raises(TypeError):
        tz.fromutc(dt)

    assert tz.fromutc_calls == 0


def test_fromutc_rejects_other_tzinfo():
    tz = _RecordingTZ()
    dt = datetime(2020, 1, 1, tzinfo=_OtherTZ())

    with pytest.raises(TypeError):
        tz.fromutc(dt)

    assert tz.fromutc_calls == 0


def test_fromutc_accepts_self_tzinfo():
    tz = _RecordingTZ()
    dt = datetime(2020, 1, 1, tzinfo=tz)

    result = tz.fromutc(dt)

    assert tz.fromutc_calls == 1
    assert result == datetime(2020, 1, 1, 2)

