from datetime import datetime, timedelta, tzinfo

from dateutil.tz._common import _validate_fromutc_inputs


class _RecordingTz(tzinfo):
    def __init__(self):
        self.utcoffset_calls = 0
        self.dst_calls = 0
        self.tzname_calls = 0

    def utcoffset(self, dt):
        self.utcoffset_calls += 1
        return timedelta(0)

    def dst(self, dt):
        self.dst_calls += 1
        return timedelta(0)

    def tzname(self, dt):
        self.tzname_calls += 1
        return "recording"

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.fromutc_calls = getattr(self, "fromutc_calls", 0) + 1
        return dt


class _OtherTz(tzinfo):
    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "other"


def test_fromutc_rejects_other_tzinfo_with_valueerror():
    tz_self = _RecordingTz()
    other = _OtherTz()
    dt = datetime(2020, 1, 1, tzinfo=other)

    with pytest.raises(ValueError):
        tz_self.fromutc(dt)

    assert getattr(tz_self, "fromutc_calls", 0) == 0


def test_fromutc_rejects_naive_datetime_with_valueerror():
    tz_self = _RecordingTz()
    dt = datetime(2020, 1, 1)

    with pytest.raises(ValueError):
        tz_self.fromutc(dt)

    assert getattr(tz_self, "fromutc_calls", 0) == 0


def test_fromutc_accepts_self_tzinfo_and_calls_wrapped():
