    wrapper = make_wrapper()
    assert wrapper.indent_only("one\ntwo\nthree\nfour") == (
        "I: one\nS: two\nS: three\nS: four"
    )


def test_blank_second_line_gets_subsequent_indent():
    wrapper = make_wrapper(initial="A", subsequent="B")
    assert wrapper.indent_only("x\n\ny") == "Ax\nB\nBy"


