    wrapper = make_wrapper()
    assert wrapper.indent_only("") == ""


def test_empty_indents_leave_text_unchanged():
    wrapper = make_wrapper(initial="", subsequent="")
    assert wrapper.indent_only("a\nb\nc") == "a\nb\nc"

