import pytest

from click._textwrap import TextWrapper


def make_wrapper(initial="INIT:", subsequent="SUB:"):
    return TextWrapper(initial_indent=initial, subsequent_indent=subsequent)


def test_single_line_uses_initial_indent():
    wrapper = make_wrapper()
    assert wrapper.indent_only("hello") == "INIT:hello"


def test_second_line_uses_subsequent_indent():
    wrapper = make_wrapper()
    result = wrapper.indent_only("first\nsecond")
    assert result == "INIT:first\nSUB:second"


def test_three_lines_use_initial_then_subsequent():
    wrapper = make_wrapper()
    result = wrapper.indent_only("a\nb\nc")
    assert result == "INIT:a\nSUB:b\nSUB:c"


def test_empty_string_returns_empty():
    wrapper = make_wrapper()
    assert wrapper.indent_only("") == ""


def test_empty_indents_leave_text_unchanged():
    wrapper = make_wrapper(initial="", subsequent="")
    assert wrapper.indent_only("one\ntwo\nthree") == "one\ntwo\nthree"


def test_trailing_newline_dropped_by_splitlines():
    wrapper = make_wrapper()
    # splitlines drops the trailing empty line, so only two lines are indented.
    assert wrapper.indent_only("first\nsecond\n") == "INIT:first\nSUB:second"


def test_blank_second_line_still_gets_subsequent_indent():
    wrapper = make_wrapper()
    assert wrapper.indent_only("first\n\nthird") == "INIT:first\nSUB:\nSUB:third"

