from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _RecordingTZ(tzinfo):
    def __init__(self):
        self.calls = []

    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "recording"

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.calls.append(dt)
        return dt + self.utcoffset(dt)


class _OtherTZ(tzinfo):
    def utcoffset(self, dt):
        return timedelta(hours=1)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "other"


def test_fromutc_rejects_other_tzinfo_with_valueerror():
    tz = _RecordingTZ()
    other = _OtherTZ()
    dt = datetime(2020, 1, 1, tzinfo=other)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_fromutc_rejects_naive_datetime_with_valueerror():
    tz = _RecordingTZ()
    dt = datetime(2020, 1, 1)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_fromutc_rejects_non_datetime_with_typeerror():
    tz = _RecordingTZ()

    with pytest.raises(TypeError):
        tz.fromutc("2020-01-01")

    assert tz.calls == []


def test_fromutc_accepts_matching_tzinfo():
    tz = _RecordingTZ()
    dt = datetime(2020, 1, 1, tzinfo=tz)

    result = tz.fromutc(dt)

    assert tz.calls == [dt]
    assert result == dt
